import json
import copy
from datetime import datetime, timezone, timedelta

TZ = timezone(timedelta(hours=8))

MENU = [
    {"id": "1", "name": "蛋餅", "price": 30},
    {"id": "2", "name": "蘿蔔糕", "price": 35},
    {"id": "3", "name": "鐵板麵", "price": 50},
    {"id": "4", "name": "漢堡", "price": 45},
    {"id": "5", "name": "奶茶", "price": 25},
    {"id": "6", "name": "豆漿", "price": 20},
]

ORDERS = []
NEXT_ID = 1

ORDER_TYPES = ("dine_in", "takeout")
STATUSES = ("pending", "preparing", "done")

ROUTES = {
    "/menu": ("GET",),
    "/orders": ("GET", "POST"),
    "/orders/status": ("PATCH",),
    "/sales/today": ("GET",),
}


def _err(status, message):
    return status, {"error": message}


def _parse_body(body):
    if body is None:
        return None
    try:
        if isinstance(body, (bytes, bytearray)):
            text = bytes(body).decode("utf-8")
        else:
            text = str(body)
        if not text.strip():
            return None
        data = json.loads(text)
    except Exception:
        return None
    if not isinstance(data, dict):
        return None
    return data


def _get_menu():
    return 200, {"items": copy.deepcopy(MENU)}


def _create_order(data):
    global NEXT_ID
    order_type = data.get("order_type")
    if not isinstance(order_type, str) or order_type not in ORDER_TYPES:
        return _err(400, "訂單類型不正確，請選擇內用或外帶")

    table_no = data.get("table_no")
    if table_no is None:
        table_no = ""
    if not isinstance(table_no, (str, int)) or isinstance(table_no, bool):
        return _err(400, "桌號格式不正確")
    table_no = str(table_no).strip()
    if order_type == "dine_in" and not table_no:
        return _err(400, "內用必須填寫桌號")
    if order_type == "takeout":
        table_no = table_no or ""

    lines_in = data.get("lines")
    if not isinstance(lines_in, list) or len(lines_in) == 0:
        return _err(400, "購物車不可為空")

    menu_by_id = {m["id"]: m for m in MENU}
    lines = []
    total = 0
    for ln in lines_in:
        if not isinstance(ln, dict):
            return _err(400, "購物車內容格式不正確")
        raw_id = ln.get("item_id")
        if raw_id is None or isinstance(raw_id, (bool, dict, list)):
            return _err(400, "找不到此餐點")
        item = menu_by_id.get(str(raw_id))
        if item is None:
            return _err(400, "找不到此餐點")
        qty = ln.get("quantity")
        if not isinstance(qty, int) or isinstance(qty, bool) or qty < 1:
            return _err(400, "數量至少為 1")
        subtotal = item["price"] * qty
        total += subtotal
        lines.append({
            "item_id": item["id"],
            "name": item["name"],
            "price": item["price"],
            "quantity": qty,
            "subtotal": subtotal,
        })

    order = {
        "id": str(NEXT_ID),
        "order_type": order_type,
        "table_no": table_no,
        "lines": lines,
        "total": total,
        "status": "pending",
        "created_at": datetime.now(TZ).isoformat(timespec="seconds"),
    }
    NEXT_ID += 1
    ORDERS.append(order)
    return 201, copy.deepcopy(order)


def _list_orders():
    return 200, {"items": copy.deepcopy(ORDERS)}


def _update_status(data):
    status = data.get("status")
    if not isinstance(status, str) or status not in STATUSES:
        return _err(400, "狀態不正確，只能是 pending、preparing 或 done")
    raw_id = data.get("order_id")
    if raw_id is None or isinstance(raw_id, (bool, dict, list)):
        return _err(404, "找不到此訂單")
    oid = str(raw_id)
    for order in ORDERS:
        if order["id"] == oid:
            order["status"] = status
            return 200, copy.deepcopy(order)
    return _err(404, "找不到此訂單")


def _sales_today():
    today = datetime.now(TZ).date()
    count = 0
    amount = 0
    qty_by_item = {}
    names = {}
    for order in ORDERS:
        try:
            created = datetime.fromisoformat(order["created_at"]).astimezone(TZ).date()
        except Exception:
            continue
        if created != today:
            continue
        count += 1
        amount += order["total"]
        for ln in order["lines"]:
            iid = ln["item_id"]
            qty_by_item[iid] = qty_by_item.get(iid, 0) + ln["quantity"]
            names[iid] = ln["name"]

    def sort_key(iid):
        try:
            n = int(iid)
        except Exception:
            n = 0
        return (-qty_by_item[iid], n)

    ranked = sorted(qty_by_item.keys(), key=sort_key)[:3]
    top = [{"item_id": iid, "name": names[iid], "quantity": qty_by_item[iid]} for iid in ranked]
    return 200, {"order_count": count, "total_amount": amount, "top_items": top}


def handle(method, path, body):
    method = (method or "").upper()
    path = path or "/"
    if not path.startswith("/"):
        path = "/" + path
    if len(path) > 1:
        path = path.rstrip("/") or "/"

    allowed = ROUTES.get(path)
    if allowed is None:
        return _err(404, "找不到此路徑")
    if method not in allowed:
        return _err(405, "不支援此請求方法")

    if path == "/menu":
        return _get_menu()
    if path == "/sales/today":
        return _sales_today()
    if path == "/orders" and method == "GET":
        return _list_orders()

    data = _parse_body(body)
    if data is None:
        return _err(400, "請求內容不是有效的 JSON 物件")
    if path == "/orders":
        return _create_order(data)
    return _update_status(data)

