(function () {
  var STATUS = { pending: '待做', preparing: '製作中', done: '完成' };
  var TYPES = { dine_in: '內用', takeout: '外帶' };
  var menu = [];
  var cart = [];
  var timer = null;
  var loadingKitchen = false;
  var sending = false;
  var current = 'order';

  function $(id) { return document.getElementById(id); }
  function h(tag, cls, text) {
    var e = document.createElement(tag);
    if (cls) e.className = cls;
    if (text !== undefined && text !== null) e.textContent = String(text);
    return e;
  }
  function money(n) { return 'NT$ ' + n; }

  function api(method, path, body) {
    var opt = { method: method, headers: {} };
    if (body !== undefined) {
      opt.headers['Content-Type'] = 'application/json';
      opt.body = JSON.stringify(body);
    }
    return fetch('api/' + path, opt).then(function (res) {
      return res.text().then(function (t) {
        var d = null;
        try { d = t ? JSON.parse(t) : null; } catch (e) { d = null; }
        if (!res.ok) {
          var m = d && d.error ? d.error : '請求失敗（HTTP ' + res.status + '）';
          throw new Error(m);
        }
        if (!d || typeof d !== 'object') throw new Error('伺服器回應格式錯誤');
        return d;
      });
    }, function () {
      throw new Error('無法連線到伺服器，請稍後再試');
    });
  }

  function showMsg(id, text, ok) {
    var e = $(id);
    if (!text) { e.textContent = ''; e.className = 'msg hidden'; return; }
    e.textContent = text;
    e.className = 'msg ' + (ok ? 'ok' : 'err');
  }

  /* Tabs */
  function showTab(name) {
    current = name;
    var tabs = document.querySelectorAll('.tab');
    for (var i = 0; i < tabs.length; i++) {
      tabs[i].classList.toggle('active', tabs[i].getAttribute('data-tab') === name);
    }
    ['order', 'kitchen', 'sales'].forEach(function (n) {
      $('tab-' + n).classList.toggle('hidden', n !== name);
    });
    if (timer) { clearInterval(timer); timer = null; }
    if (name === 'order') {
      loadMenu();
    } else if (name === 'kitchen') {
      loadKitchen();
      timer = setInterval(loadKitchen, 5000);
    } else {
      loadSales();
    }
  }

  /* Menu */
  function loadMenu() {
    api('GET', 'menu').then(function (d) {
      menu = d.items || [];
      renderMenu();
    }).catch(function (e) {
      showMsg('order-msg', '載入菜單失敗：' + e.message, false);
    });
  }
  function renderMenu() {
    var box = $('menu-list');
    box.textContent = '';
    if (!menu.length) { box.appendChild(h('p', 'muted', '目前沒有餐點')); return; }
    menu.forEach(function (m) {
      var row = h('div', 'row');
      var info = h('div', 'grow');
      info.appendChild(h('strong', '', m.name));
      info.appendChild(h('span', 'muted', ' ' + money(m.price)));
      row.appendChild(info);
      var b = h('button', 'secondary', '加入');
      b.type = 'button';
      b.setAttribute('data-add', String(m.id));
      row.appendChild(b);
      box.appendChild(row);
    });
  }

  /* Cart */
  function findCart(id) {
    for (var i = 0; i < cart.length; i++) if (String(cart[i].id) === String(id)) return i;
    return -1;
  }
  function addToCart(id) {
    var i = findCart(id);
    if (i >= 0) { cart[i].quantity += 1; }
    else {
      for (var j = 0; j < menu.length; j++) {
        if (String(menu[j].id) === String(id)) {
          cart.push({ id: String(menu[j].id), name: menu[j].name, price: menu[j].price, quantity: 1 });
        }
      }
    }
    renderCart();
  }
  function changeCart(id, act) {
    var i = findCart(id);
    if (i < 0) return;
    if (act === 'inc') cart[i].quantity += 1;
    else if (act === 'dec') cart[i].quantity -= 1;
    else if (act === 'del') cart[i].quantity = 0;
    if (cart[i].quantity <= 0) cart.splice(i, 1);
    renderCart();
  }
  function renderCart() {
    var box = $('cart-list');
    box.textContent = '';
    var total = 0;
    if (!cart.length) box.appendChild(h('p', 'muted', '購物車是空的'));
    cart.forEach(function (c) {
      var sub = c.price * c.quantity;
      total += sub;
      var row = h('div', 'row');
      var info = h('div', 'grow');
      info.appendChild(h('strong', '', c.name));
      info.appendChild(h('div', 'muted', money(c.price) + ' × ' + c.quantity + ' = ' + money(sub)));
      row.appendChild(info);
      var ctr = h('div', 'ctr');
      [['dec', '−'], ['inc', '+'], ['del', '移除']].forEach(function (p) {
        var b = h('button', p[0] === 'del' ? 'secondary small' : 'qty', p[1]);
        b.type = 'button';
        b.setAttribute('data-act', p[0]);
        b.setAttribute('data-id', c.id);
        ctr.appendChild(b);
      });
      row.appendChild(ctr);
      box.appendChild(row);
    });
    $('cart-total').textContent = money(total);
  }
  function orderType() {
    var r = document.querySelector('input[name=order_type]:checked');
    return r ? r.value : 'dine_in';
  }
  function updateTableField() {
    $('table-wrap').classList.toggle('dim', orderType() === 'takeout');
  }
  function submitOrder() {
    if (sending) return;
    showMsg('order-msg', '');
    var type = orderType();
    var table = $('table-no').value.trim();
    if (!cart.length) { showMsg('order-msg', '購物車是空的，請先選擇餐點', false); return; }
    if (type === 'dine_in' && !table) { showMsg('order-msg', '內用請填寫桌號', false); return; }
    var body = {
      order_type: type,
      table_no: type === 'dine_in' ? table : table,
      lines: cart.map(function (c) { return { item_id: c.id, quantity: c.quantity }; })
    };
    sending = true;
    $('submit-order').disabled = true;
    api('POST', 'orders', body).then(function (o) {
      showMsg('order-msg', '訂單已送出！編號 ' + o.id + '，總金額 ' + money(o.total), true);
      cart = [];
      $('table-no').value = '';
      renderCart();
    }).catch(function (e) {
      showMsg('order-msg', '送出訂單失敗：' + e.message, false);
    }).then(function () {
      sending = false;
      $('submit-order').disabled = false;
    });
  }

  /* Kitchen */
  function fmtTime(s) {
    var d = new Date(s);
    if (isNaN(d.getTime())) return String(s || '');
    function p(n) { return n < 10 ? '0' + n : '' + n; }
    return p(d.getHours()) + ':' + p(d.getMinutes());
  }
  function loadKitchen() {
    if (loadingKitchen) return;
    loadingKitchen = true;
    api('GET', 'orders').then(function (d) {
      if (current !== 'kitchen') return;
      renderKitchen(d.items || []);
      showMsg('kitchen-msg', '');
    }).catch(function (e) {
      showMsg('kitchen-msg', '載入訂單失敗：' + e.message, false);
    }).then(function () { loadingKitchen = false; });
  }
  function renderKitchen(items) {
    var box = $('kitchen-list');
    box.textContent = '';
    if (!items.length) { box.appendChild(h('p', 'muted', '目前沒有訂單')); return; }
    items.forEach(function (o) {
      var card = h('div', 'card order st-' + o.status);
      var head = h('div', 'ohead');
      head.appendChild(h('strong', '', '#' + o.id));
      var t = TYPES[o.order_type] || o.order_type;
      if (o.table_no) t += '　桌號 ' + o.table_no;
      head.appendChild(h('span', '', t));
      head.appendChild(h('span', 'muted', fmtTime(o.created_at)));
      head.appendChild(h('span', 'badge', STATUS[o.status] || o.status));
      card.appendChild(head);
      var ul = h('ul', 'lines');
      (o.lines || []).forEach(function (l) {
        ul.appendChild(h('li', '', l.name + ' × ' + l.quantity));
      });
      card.appendChild(ul);
      card.appendChild(h('div', 'muted', '合計 ' + money(o.total)));
      var bar = h('div', 'ctr wrap');
      ['pending', 'preparing', 'done'].forEach(function (s) {
        var b = h('button', s === o.status ? 'primary small' : 'secondary small', STATUS[s]);
        b.type = 'button';
        b.setAttribute('data-order', String(o.id));
        b.setAttribute('data-status', s);
        bar.appendChild(b);
      });
      card.appendChild(bar);
      box.appendChild(card);
    });
  }
  function setStatus(id, status) {
    api('PATCH', 'orders/status', { order_id: id, status: status }).then(function () {
      showMsg('kitchen-msg', '');
      loadKitchen();
    }).catch(function (e) {
      showMsg('kitchen-msg', '更新狀態失敗：' + e.message, false);
    });
  }

  /* Sales */
  function loadSales() {
    api('GET', 'sales/today').then(function (d) {
      showMsg('sales-msg', '');
      var box = $('sales-body');
      box.textContent = '';
      var stats = h('div', 'stats');
      var a = h('div', 'card stat');
      a.appendChild(h('div', 'muted', '今日訂單數'));
      a.appendChild(h('div', 'big', d.order_count));
      var b = h('div', 'card stat');
      b.appendChild(h('div', 'muted', '今日總金額'));
      b.appendChild(h('div', 'big', money(d.total_amount)));
      stats.appendChild(a);
      stats.appendChild(b);
      box.appendChild(stats);
      var c = h('div', 'card');
      c.appendChild(h('h2', '', '前三名品項'));
      var top = (d.top_items || []).slice(0, 3);
      if (!top.length) c.appendChild(h('p', 'muted', '尚無銷售資料'));
      var ol = h('ol', 'lines');
      top.forEach(function (t) { ol.appendChild(h('li', '', t.name + '：' + t.quantity + ' 份')); });
      if (top.length) c.appendChild(ol);
      box.appendChild(c);
    }).catch(function (e) {
      showMsg('sales-msg', '載入營業額失敗：' + e.message, false);
    });
  }

  /* Events */
  document.addEventListener('DOMContentLoaded', function () {
    var tabs = document.querySelectorAll('.tab');
    for (var i = 0; i < tabs.length; i++) {
      tabs[i].addEventListener('click', function (ev) {
        showTab(ev.currentTarget.getAttribute('data-tab'));
      });
    }
    $('menu-list').addEventListener('click', function (ev) {
      var b = ev.target.closest('button[data-add]');
      if (b) addToCart(b.getAttribute('data-add'));
    });
    $('cart-list').addEventListener('click', function (ev) {
      var b = ev.target.closest('button[data-act]');
      if (b) changeCart(b.getAttribute('data-id'), b.getAttribute('data-act'));
    });
    $('kitchen-list').addEventListener('click', function (ev) {
      var b = ev.target.closest('button[data-order]');
      if (b) setStatus(b.getAttribute('data-order'), b.getAttribute('data-status'));
    });
    var radios = document.querySelectorAll('input[name=order_type]');
    for (var j = 0; j < radios.length; j++) radios[j].addEventListener('change', updateTableField);
    $('submit-order').addEventListener('click', submitOrder);
    $('sales-refresh').addEventListener('click', loadSales);
    renderCart();
    updateTableField();
    showTab('order');
  });
})();

